import type { Json, RuntimeMode } from "../src/lib/types";

export type PythonLesson = {
  key: string; task: string; objective: string; theory: string; code: string; starter: string;
  cases: [Json, Json][]; hints: [string, string, string]; explanation: string;
  runtimeMode: RuntimeMode;
};
export const pythonLessons = new Map<string, PythonLesson>();
function lesson(key: string, task: string, objective: string, theory: string, code: string, cases: [Json, Json][], hints: [string, string, string], explanation: string, starter = "return None", runtimeMode: RuntimeMode = "FUNCTION") {
  pythonLessons.set(`python-${key}`, { key: `python-${key}`, task, objective, theory, code, starter, cases, hints, explanation, runtimeMode });
}

lesson("constante", "No hay entrada. Tienes 3 cajas y cada una contiene 6 lápices. Guarda LAPICES_POR_CAJA = 6 y cajas = 3. Muestra el total utilizando esos nombres. La salida debe ser una línea con 18; la comprobación observa el resultado y no puede certificar que hayas escrito la constante.", "Representar una equivalencia fija con un nombre significativo.", "Un nombre en MAYÚSCULAS comunica una equivalencia fija por convención. Python no impide reasignarlo; la garantía es del programa y de la revisión humana. La multiplicación combina la cantidad variable con la equivalencia. En otro problema, IVA = 0.21 y precio * IVA aplicarían el mismo patrón.", "LAPICES_POR_CAJA = 6\ncajas = 3\nprint(cajas * LAPICES_POR_CAJA)", [["","18\n"]], ["La equivalencia no cambia entre cajas.", "Cada caja aporta seis lápices.", "Multiplica cajas por LAPICES_POR_CAJA; no escribas 18 directamente."], "Para tres cajas hay 6 + 6 + 6 = 18 lápices. El nombre de la constante hace explícito el significado del seis. La salida sola no demuestra el uso de mayúsculas: la convención se explica aquí y se conserva en el código.", "cajas = 3\nprint(0)", "PROGRAM");
lesson("decimal", "La entrada contiene un decimal finito entre -100 y 100 en una línea, con punto como separador. La plantilla ya lee el texto, pero no lo convierte. Conviértelo a float, súmale 0.5 y muestra el resultado. La entrada siempre es válida. Conserva la representación habitual de print para un float, incluido .0 cuando corresponde.", "Convertir texto decimal antes de calcular.", "float('1.5') produce el número 1.5. int no acepta ese texto decimal. print muestra 2.0 al sumar 1.5 + 0.5 porque el resultado es un float. Más adelante aprenderás a devolver números y a formatearlos como texto.", "texto = input()\nnumero = float(texto)\nprint(numero + 0.5)", [["0.5\n","1.0\n"],["-0.5\n","0.0\n"],["1.5\n","2.0\n"],["0\n","0.5\n"],["-2.25\n","-1.75\n"],["100\n","100.5\n"]], ["La plantilla lee, pero todavía no convierte el texto.", "Convierte con float(texto), no con int.", "Suma 0.5 al número convertido y muestra el cálculo."], "La conversión cambia el tipo antes de sumar. Para '-2.25', sumar 0.5 da -1.75. print conserva el .0 cuando el resultado es un float entero.", "texto = input()\nprint(0.0)", "PROGRAM");
lesson("condicional", "Recibes una edad entera de 0 a 120. Devuelve 'adulto' desde los 18 años y 'menor' en otro caso. Practica una expresión condicional sencilla.", "Elegir entre dos valores mediante una expresión condicional.", "En 'sí' if condicion else 'no', primero se comprueba la condición y se obtiene uno de los textos. Equivale a if/else con dos retornos; no hace falta anidar expresiones.", "return 'adulto' if data >= 18 else 'menor'", [[18,"adulto"],[17,"menor"],[0,"menor"],[120,"adulto"]], ["La mayoría de edad incluye 18.", "La condición va entre las dos respuestas.", "Devuelve 'adulto' if data >= 18 else 'menor'."], "La igualdad pertenece a la rama de adulto. Comparar solo con > dejaría fuera el límite de 18.");
lesson("centinela", "Recibes una lista de enteros entre -100 y 100. Devuelve los elementos anteriores al primer cero; no incluyas el cero ni los posteriores. Si no hay cero, devuelve todos. No modifiques la entrada.", "Terminar un recorrido cuando aparece un centinela.", "break termina inmediatamente el bucle más cercano. Comprueba el centinela antes de añadir el elemento. Una lista vacía no ejecuta vueltas y devuelve [].", "salida = []\nfor n in data:\n    if n == 0:\n        break\n    salida.append(n)\nreturn salida", [[[2,0,8],[2]],[[0,4],[]],[[1,-2],[1,-2]],[[],[]]], ["No basta con ignorar los ceros: también se omite lo posterior.", "La comprobación debe preceder a append.", "Cuando n sea cero, utiliza break; en otro caso añade n."], "Para [2, 0, 8] se añade 2 y el cero termina el bucle, así que nunca se visita el 8.", "salida = []\nfor n in data:\n    salida.append(n)\nreturn salida");
lesson("omite-negativos", "Recibes una lista de enteros entre -100 y 100. Devuelve los no negativos en su orden original, conservando ceros y repeticiones. Practica continue; no detengas el recorrido tras un negativo.", "Omitir una vuelta sin terminar el recorrido.", "continue salta a la siguiente vuelta. A diferencia de break, permite procesar valores posteriores. Usa n < 0 para omitir negativos sin perder el cero.", "salida = []\nfor n in data:\n    if n < 0:\n        continue\n    salida.append(n)\nreturn salida", [[[-1,0,3],[0,3]],[[],[]],[[-2,-1],[]],[[2,2],[2,2]]], ["Después de un negativo puede haber datos válidos.", "Cero debe conservarse.", "Usa continue cuando n < 0; añade n en los demás casos."], "En [-1, 0, 3] se omite la primera vuelta, no el bucle completo. El resultado conserva 0 y 3.");
lesson("ordena-numeros", "Recibes una lista de enteros entre -100 y 100. Devuelve {original, ordenados}: original conserva la entrada y ordenados contiene sus valores de menor a mayor, con repeticiones. También se permite la lista vacía.", "Ordenar una copia sin modificar la lista recibida.", "sorted(lista) crea una lista nueva. lista.sort() modifica esa lista y devuelve None: no son intercambiables. En un resultado con nombre se usan claves de diccionario como 'original'.", "return {'original': data, 'ordenados': sorted(data)}", [[ [3,1,3],{original:[3,1,3],ordenados:[1,3,3]}],[[],{original:[],ordenados:[]}],[[-1,-3,0],{original:[-1,-3,0],ordenados:[-3,-1,0]}]], ["Conservar la entrada forma parte del resultado.", "Necesitas una lista ordenada nueva.", "Devuelve data como original y sorted(data) como ordenados."], "[3, 1, 3] produce [1, 3, 3] al ordenar, pero original sigue empezando por 3. No elimines duplicados.");
lesson("recorta", "Recibes {valores, inicio, fin}. valores es una lista de enteros y 0 ≤ inicio ≤ fin ≤ longitud. Devuelve el tramo desde inicio incluido hasta fin excluido. No modifiques valores.", "Extraer una rebanada con límite superior exclusivo.", "lista[a:b] copia posiciones desde a hasta antes de b. Si a == b, el tramo es vacío. A diferencia de una consulta de índice, el resultado es otra lista.", "return data['valores'][data['inicio']:data['fin']]", [[{valores:[4,8,2],inicio:1,fin:3},[8,2]],[{valores:[],inicio:0,fin:0},[]],[{valores:[9],inicio:0,fin:0},[]],[{valores:[9],inicio:0,fin:1},[9]]], ["fin no pertenece al tramo.", "Los dos límites pueden coincidir.", "Utiliza valores[inicio:fin]."], "Desde 1 hasta 3 se copian los índices 1 y 2. No sumes uno a fin: ya es exclusivo.");
lesson("une-palabras", "Recibes un texto ASCII con palabras separadas por espacios, tabulaciones o saltos de línea. Devuelve las mismas palabras separadas por un único espacio, sin espacios en los extremos. Conserva mayúsculas y signos. Un texto sin palabras devuelve ''.", "Separar y reconstruir texto con una normalización precisa.", "texto.split() sin argumento separa por espacios en blanco y omite grupos vacíos. ' '.join(palabras) une textos con un espacio. No equivale a split(' '), que puede conservar posiciones vacías.", "return ' '.join(data.split())", [["  Hola   Mundo ","Hola Mundo"],["\tuno\ndos","uno dos"],["   ",""],["A!","A!"]], ["No cambies las letras ni la puntuación.", "split sin argumento reconoce varios tipos de espacio.", "Une data.split() mediante ' '.join(...)."], "Separar primero evita tener que contar espacios consecutivos. Con solo espacios se obtiene [] y join produce el texto vacío.");
lesson("desempaqueta", "Recibes una lista de exactamente dos enteros. Desempaqueta sus valores en a y b y devuelve la pareja invertida como [b, a]. No modifiques la lista original.", "Desempaquetar una pareja antes de intercambiar sus valores.", "a, b = pareja requiere exactamente dos elementos. a, b = b, a calcula primero la derecha y luego asigna. Una tupla devuelta se serializa como un arreglo JSON; el juez comprueba los valores, no la sintaxis usada.", "a, b = data\na, b = b, a\nreturn a, b", [[[3,8],[8,3]],[[0,0],[0,0]],[[-2,5],[5,-2]]], ["La entrada tiene exactamente dos posiciones.", "El intercambio se evalúa antes de modificar a y b.", "Desempaqueta, intercambia con a, b = b, a y devuelve ambos."], "La derecha conserva los dos valores previos, por eso el intercambio no pierde el primero. Es una alternativa posterior al intercambio con auxiliar.");
lesson("enumera", "Recibes una lista de palabras. Devuelve una lista de parejas [posición, palabra], numeradas desde 1 y en el mismo orden. Conserva palabras repetidas. Una lista vacía devuelve [].", "Recorrer índice y valor mediante enumerate.", "enumerate(valores, 1) entrega parejas (1, primer_valor), (2, segundo_valor)... Se desempaquetan en la cabecera del for. El segundo argumento cambia el comienzo de la numeración.", "salida = []\nfor posicion, palabra in enumerate(data, 1):\n    salida.append([posicion, palabra])\nreturn salida", [[["sol","luz"],[[1,"sol"],[2,"luz"]]],[[],[]],[["a","a"],[[1,"a"],[2,"a"]]]], ["No busques la posición por el valor: puede repetirse.", "La numeración empieza en uno.", "Recorre enumerate(data, 1) y añade cada pareja."], "enumerate distingue posiciones aunque las palabras sean iguales. No necesitas actualizar un contador manual.");
lesson("empareja", "Recibes {a, b}, dos listas de enteros que pueden tener distinta longitud. Devuelve parejas con un elemento de cada lista, en orden. Termina al agotarse la más corta y no rellenes posiciones.", "Emparejar secuencias con el comportamiento de zip.", "zip(a, b) entrega parejas de valores correspondientes y termina al agotarse cualquiera de las entradas. Se puede recorrer con for x, y in zip(a, b). Materializa la salida en una lista para devolver JSON.", "salida = []\nfor a, b in zip(data['a'], data['b']):\n    salida.append([a, b])\nreturn salida", [[{a:[1,2],b:[3]},[[1,3]]],[{a:[],b:[4]},[]],[{a:[0],b:[0,8]},[[0,0]]]], ["No hay que completar con ceros ni None.", "El tamaño de salida es el mínimo de ambas longitudes.", "Añade una pareja por cada vuelta de zip(data['a'], data['b'])."], "La segunda posición de [1, 2] no tiene pareja en [3], por eso no aparece. Una entrada vacía produce cero parejas.");
lesson("retorno-multiple", "Recibes exactamente dos enteros. Define una auxiliar que reciba ambos y devuelva su suma y su producto juntos. Desde solve, devuelve esos resultados en ese orden. Itera los muestra como una lista de dos números.", "Entregar y desempaquetar varios resultados de una auxiliar.", "return suma, producto devuelve una tupla. s, p = auxiliar(a, b) recupera ambos valores. No son dos retornos separados: solo se ejecuta el primer return de una llamada.", "def resumen(a, b):\n    return a + b, a * b\nsuma, producto = resumen(data[0], data[1])\nreturn suma, producto", [[[2,3],[5,6]],[[0,4],[4,0]],[[-2,3],[1,-6]]], ["El orden de los dos resultados importa.", "Un return puede agrupar ambos cálculos.", "La auxiliar devuelve a + b, a * b; desempaqueta sus resultados."], "Para 2 y 3, la misma llamada produce (5, 6). solve entrega ambos valores, sin imprimirlos ni hacer una segunda llamada.");
lesson("identidad", "Recibes {valores, nuevo}. Construye original = list(data['valores']). Guarda alias = original y copia = list(original). Conserva antes = list(original), añade nuevo solo al alias y devuelve {antes, original, copia, igual, misma, copiaMisma}. original es el alias ya modificado; igual compara original y copia por contenido; misma indica si alias es original; copiaMisma indica si copia es original (será False). No añadas nuevo a la copia ni modifiques data.", "Distinguir igualdad de contenido, identidad y efectos de mutar un alias.", "== compara contenido; is pregunta si es el mismo objeto. original se construye desde data y alias = original no lo copia: mutar el alias cambia original. list(...) crea otra lista; mutar la copia no cambia original. El JSON devuelto muestra los efectos, pero solo el código y las comparaciones is explican la identidad.", "original = list(data['valores'])\nalias = original\nantes = list(original)\ncopia = list(original)\nalias.append(data['nuevo'])\nreturn {'antes': antes, 'original': alias, 'copia': copia, 'igual': alias == copia, 'misma': alias is original, 'copiaMisma': copia is original}", [[{valores:[1,2],nuevo:3},{antes:[1,2],original:[1,2,3],copia:[1,2],igual:false,misma:true,copiaMisma:false}],[{valores:[],nuevo:0},{antes:[],original:[0],copia:[],igual:false,misma:true,copiaMisma:false}],[{valores:[2,2],nuevo:2},{antes:[2,2],original:[2,2,2],copia:[2,2],igual:false,misma:true,copiaMisma:false}],[{valores:[-1,0],nuevo:-1},{antes:[-1,0],original:[-1,0,-1],copia:[-1,0],igual:false,misma:true,copiaMisma:false}]], ["Guarda antes de mutar el alias.", "Añade nuevo solo al alias; la copia debe conservar sus valores.", "Usa == para contenido e is para comparar alias/copia con original."], "Para [1,2] y nuevo 3, antes queda [1,2], original [1,2,3] y copia [1,2]. igual es False porque el alias mutó el original; misma es True porque alias y original son el mismo objeto; copiaMisma es False porque list creó otra lista.", "return {'antes': [], 'original': [], 'copia': [], 'igual': False, 'misma': False, 'copiaMisma': False}");
lesson("opcional-seguro", "Recibes exactamente dos enteros. La auxiliar agregar(valor, base=None) debe crear una lista nueva cuando se omite base. Llámala una vez por entero sin pasar base y devuelve ambas listas. La segunda llamada no debe heredar el primer valor.", "Crear el contenedor predeterminado dentro de cada llamada.", "Los valores predeterminados se calculan al definir la función. base=[] compartiría una lista entre llamadas. Con base=None, comprueba is None y crea [] dentro de la función, antes de append.", "def agregar(valor, base=None):\n    if base is None:\n        base = []\n    base.append(valor)\n    return base\nreturn [agregar(data[0]), agregar(data[1])]", [[[2,5],[[2],[5]]],[[0,0],[[0],[0]]],[[-1,3],[[-1],[3]]]], ["Cada llamada tiene que comenzar sin elementos anteriores.", "None es una señal para crear una lista dentro de la llamada.", "Comprueba base is None, asigna [] y después añade valor."], "Con dos llamadas se detecta la acumulación accidental. Los dos resultados deben seguir separados aunque los valores sean iguales.");
lesson("actualiza-diccionario", "Recibes {valores, clave, nuevo}. valores es un diccionario de texto a entero. Devuelve una copia con clave asociada a nuevo: si ya existía, reemplázala; si faltaba, añádela. Conserva las demás parejas y no cambies el original.", "Añadir y reemplazar claves de una copia de diccionario.", "dict(original) copia un diccionario plano. copia[clave] = nuevo sirve tanto para insertar como para reemplazar. No hace falta eliminar primero la clave.", "copia = dict(data['valores'])\ncopia[data['clave']] = data['nuevo']\nreturn copia", [[{valores:{a:2},clave:"b",nuevo:3},{a:2,b:3}],[{valores:{a:2},clave:"a",nuevo:0},{a:0}],[{valores:{},clave:"x",nuevo:-1},{x:-1}]], ["Empieza por una copia para conservar la entrada.", "La asignación por clave cubre ambos casos.", "Asigna nuevo a copia[clave] y devuelve copia."], "Una clave no se duplica: asignar a una existente cambia su valor. El cero debe conservarse como cualquier otro entero.");
lesson("borra-clave", "Recibes {valores, clave}, un diccionario de texto a entero y la clave que quieres borrar. Devuelve una copia sin esa clave. Si no existe, conserva todas las parejas. No modifiques el original.", "Eliminar una clave ausente sin provocar KeyError.", "copia.pop(clave, None) elimina y devuelve el valor si existe; si falta devuelve el respaldo None sin error. El dato eliminado puede valer cero: no compruebes su verdad para decidir qué devolver.", "copia = dict(data['valores'])\ncopia.pop(data['clave'], None)\nreturn copia", [[{valores:{a:0,b:2},clave:"a"},{b:2}],[{valores:{a:1},clave:"z"},{a:1}],[{valores:{},clave:"a"},{}]], ["La clave puede no existir.", "pop admite un respaldo para evitar KeyError.", "Copia valores, llama pop(clave, None) y devuelve la copia."], "Borrar a cuando vale cero funciona igual que con cualquier valor. Una clave ausente no cambia el diccionario.");
lesson("recorre-pares", "Recibes un diccionario con claves formadas por letras a-z y valores enteros. Devuelve una lista de textos 'clave: valor', ordenados por clave ascendente. Un diccionario vacío devuelve [].", "Recorrer claves y valores con un orden de salida explícito.", "items entrega parejas; keys y values ofrecen vistas de claves y valores. sorted(d.items()) ordena parejas primero por clave. En el for puedes desempaquetar clave, valor y convertir el número con str.", "salida = []\nfor clave, valor in sorted(data.items()):\n    salida.append(clave + ': ' + str(valor))\nreturn salida", [[{b:2,a:0},["a: 0","b: 2"]],[{},[]],[{x:-3},["x: -3"]]], ["La salida es una lista de textos, no un diccionario.", "Ordena las parejas por sus claves.", "Recorre sorted(data.items()) y construye clave + ': ' + str(valor)."], "El orden pedido no depende de cómo llegaron las propiedades. Convertir valor con str evita intentar sumar un texto y un entero.");
lesson("lista-registros", "Recibes una lista de diccionarios con nombre (texto) y cantidad (entero no negativo). Devuelve el total de cantidades; no agrupes por nombre ni elimines registros repetidos. La lista vacía devuelve cero.", "Combinar un recorrido de lista con acceso a un campo.", "En for ficha in registros, cada ficha es un diccionario. ficha['cantidad'] consulta ese campo; no es una posición de la lista. Un acumulador se inicializa antes del recorrido y se devuelve después.", "total = 0\nfor ficha in data:\n    total += ficha['cantidad']\nreturn total", [[[{nombre:"pan",cantidad:2},{nombre:"pan",cantidad:3}],5],[[],0],[[{nombre:"agua",cantidad:0}],0]], ["Cada registro cuenta, aunque se repita el nombre.", "Accede a cantidad dentro de cada ficha.", "Acumula ficha['cantidad'] en total y devuelve total al terminar."], "Dos registros de pan con cantidades 2 y 3 aportan 5. No hace falta crear claves dinámicas para este primer recorrido de registros.");
lesson("conjunto-seguro", "Recibes {valores, agregar, quitar}, con una lista de enteros y dos enteros. Convierte valores en conjunto, añade agregar y después descarta quitar. Devuelve los elementos restantes de menor a mayor y sin repeticiones.", "Actualizar un conjunto sin fallar por un elemento ausente.", "set elimina duplicados. add incorpora un solo elemento; discard elimina si existe y no falla si falta. remove sí falla si falta. sorted convierte el conjunto a una lista ordenada serializable.", "conjunto = set(data['valores'])\nconjunto.add(data['agregar'])\nconjunto.discard(data['quitar'])\nreturn sorted(conjunto)", [[{valores:[2,2],agregar:3,quitar:9},[2,3]],[{valores:[],agregar:1,quitar:1},[]],[{valores:[-1,0],agregar:0,quitar:-1},[0]]], ["El orden de las dos operaciones importa si agregar y quitar coinciden.", "discard permite quitar un elemento ausente.", "Aplica add, luego discard y devuelve sorted del conjunto."], "Cuando se añade y después se quita el mismo valor no queda en la salida. La lista ordenada hace determinista la respuesta.");
lesson("union", "Recibes {a, b}, dos listas de enteros. Devuelve todos los valores presentes en al menos una de ellas, sin repeticiones y de menor a mayor. Se permiten listas vacías.", "Construir la unión de dos conjuntos.", "A | B incluye lo que está en A, en B o en ambos. Los elementos compartidos aparecen una sola vez. Convierte las listas con set y materializa la salida con sorted.", "return sorted(set(data['a']) | set(data['b']))", [[{a:[1,2],b:[2,3]},[1,2,3]],[{a:[],b:[]},[]],[{a:[-2,-2],b:[0]},[-2,0]]], ["No se pide solo la parte compartida.", "La unión incluye elementos exclusivos y comunes.", "Usa | entre los conjuntos y ordena el resultado."], "[1, 2] y [2, 3] se unen en [1, 2, 3]. El 2 no se duplica aunque aparezca en las dos entradas.");
lesson("interseccion", "Recibes {a, b}, dos listas de enteros. Devuelve los valores presentes en ambas, sin repeticiones y de menor a mayor. Si no comparten valores, devuelve [].", "Construir la intersección de dos conjuntos.", "A & B conserva solo lo compartido. No cuenta cuántas veces aparece un valor. Un conjunto vacío no tiene elementos en común con otro.", "return sorted(set(data['a']) & set(data['b']))", [[{a:[1,2,2],b:[2,3]},[2]],[{a:[],b:[2]},[]],[{a:[-1,0],b:[0,-1]},[-1,0]]], ["El valor debe figurar en las dos listas.", "No conserves cantidades de repeticiones.", "Usa & y convierte su resultado con sorted."], "Aunque el 2 se repita en a, solo hay un elemento 2 en la intersección. No uses concatenación ni unión.");
lesson("diferencia", "Recibes {disponibles, requeridos}, dos listas de textos de letras a-z. Devuelve los requeridos que no están disponibles, sin repeticiones y en orden alfabético. Las listas pueden estar vacías.", "Calcular faltantes respetando la dirección de la diferencia.", "A - B conserva lo que está en A y no en B. El orden importa: requeridos - disponibles representa faltantes; la resta inversa representa sobrantes.", "return sorted(set(data['requeridos']) - set(data['disponibles']))", [[{disponibles:["oro"],requeridos:["oro","mapa"]},["mapa"]],[{disponibles:[],requeridos:[]},[]],[{disponibles:["mapa"],requeridos:["oro","oro"]},["oro"]]], ["Empieza por lo que necesitas, no por lo que tienes.", "Resta disponibles a requeridos.", "Devuelve sorted(set(requeridos) - set(disponibles))."], "Si tienes oro y necesitas oro y mapa, solo falta mapa. Los elementos disponibles que no se necesitan no deben aparecer.");
lesson("simetrica", "Recibes {a, b}, dos listas de enteros. Devuelve los valores presentes en exactamente una de las listas, sin duplicados y de menor a mayor.", "Distinguir diferencia simétrica de unión e intersección.", "A ^ B excluye lo común y conserva los exclusivos de ambos lados. No es A - B: también incluye los exclusivos de B.", "return sorted(set(data['a']) ^ set(data['b']))", [[{a:[1,2],b:[2,3]},[1,3]],[{a:[],b:[2,2]},[2]],[{a:[0],b:[0]},[]]], ["Los compartidos deben desaparecer.", "Conserva exclusivos de los dos lados.", "El operador ^ calcula la diferencia simétrica."], "En [1, 2] y [2, 3], el 2 es compartido y sale; 1 y 3 se conservan. Entradas iguales producen [].");
lesson("subconjunto", "Recibes {disponibles, requeridos}, listas de textos. Devuelve un booleano que indique si todos los requeridos están disponibles. Las repeticiones no cuentan como unidades y ningún requisito significa verdadero.", "Comprobar inclusión de conjuntos, incluido el conjunto vacío.", "A <= B comprueba que todos los elementos de A pertenecen a B. Incluye igualdad; < pide además que no sean iguales. El conjunto vacío es subconjunto de cualquier conjunto.", "return set(data['requeridos']) <= set(data['disponibles'])", [[{disponibles:["a","b"],requeridos:["b"]},true],[{disponibles:[],requeridos:[]},true],[{disponibles:["a"],requeridos:["b"]},false],[{disponibles:["a"],requeridos:["a","a"]},true]], ["No se comprueban cantidades, solo pertenencia.", "La igualdad de conjuntos también satisface los requisitos.", "Compara set(requeridos) <= set(disponibles)."], "Pedir dos veces 'a' no exige dos unidades en este contrato. Si necesitaras cantidades, un conjunto no sería el modelo adecuado.");
lesson("crea-grupo", "Recibes {grupos, categoria, nombre}. grupos es un diccionario de categorías a listas de nombres. Devuelve una copia con nombre añadido al final de la lista de categoria; créala si falta. Conserva las listas originales y los nombres repetidos.", "Crear el contenedor interior antes de añadir un registro.", "Copiar solo el diccionario exterior comparte sus listas. Crea una lista nueva por categoría. setdefault(categoria, []) devuelve la lista existente o inserta una vacía, y append añade el nombre.", "copia = {}\nfor clave, nombres in data['grupos'].items():\n    copia[clave] = list(nombres)\ncopia.setdefault(data['categoria'], []).append(data['nombre'])\nreturn copia", [[{grupos:{a:["ana"]},categoria:"a",nombre:"bea"},{a:["ana","bea"]}],[{grupos:{},categoria:"b",nombre:"ana"},{b:["ana"]}],[{grupos:{a:["ana"]},categoria:"a",nombre:"ana"},{a:["ana","ana"]}]], ["Cada valor del diccionario es una lista.", "Copia también las listas que podrías modificar.", "Usa setdefault(categoria, []) antes de append(nombre)."], "Una categoría nueva empieza con una lista vacía. Una ya existente conserva sus nombres, en orden, antes del nuevo elemento.");
lesson("comprension", "Recibes una lista de enteros. Devuelve sus cuadrados en el mismo orden y con las mismas posiciones. No modifiques la lista original. Practica la comprensión equivalente a un bucle con append.", "Traducir una transformación de lista a una comprensión.", "[n * n for n in valores] calcula un resultado por cada valor. Equivale a iniciar salida = [] y añadir n * n dentro del bucle. La comprensión no elimina elementos si no hay filtro.", "return [n * n for n in data]", [[[-2,0,3],[4,0,9]],[[],[]],[[2,2],[4,4]]], ["Cada entrada corresponde a una salida.", "El cuadrado de un negativo también es no negativo.", "Coloca n * n antes de for n in data."], "Para [-2, 0, 3] la expresión se evalúa tres veces y da [4, 0, 9]. El orden y las repeticiones se conservan.");
lesson("comprension-filtro", "Recibes texto ASCII. Devuelve una lista con sus vocales a/e/i/o/u en minúsculas y en orden de aparición. Acepta mayúsculas; no elimines vocales repetidas. Un texto sin vocales devuelve [].", "Combinar normalización y filtro en una comprensión.", "El if posterior al for decide qué elementos entran. Normaliza el texto con lower antes de recorrerlo para que las vocales mayúsculas también coincidan con 'aeiou'.", "return [c for c in data.lower() if c in 'aeiou']", [["HOLA Mundo",["o","a","u","o"]],["xyz",[]],["AEae",["a","e","a","e"]],["",[]]], ["La salida debe contener vocales en minúscula.", "Normaliza antes de comprobar pertenencia.", "Recorre data.lower() y filtra con c in 'aeiou'."], "La normalización no cambia el orden. Comparar el texto original con 'aeiou' perdería las vocales mayúsculas.");
lesson("comprension-condicional", "Recibes una lista de enteros. Devuelve otra del mismo tamaño, sustituyendo cada negativo por cero y conservando los demás. No elimines posiciones ni cambies la entrada.", "Distinguir transformar condicionalmente de filtrar.", "[a if condicion else b for x in valores] obtiene un valor en todas las posiciones. [x for x in valores if condicion] elimina posiciones. Aquí necesitas la primera forma.", "return [n if n >= 0 else 0 for n in data]", [[[-2,3,0],[0,3,0]],[[],[]],[[-1,-1],[0,0]]], ["El tamaño no puede cambiar.", "El if debe formar parte de la expresión anterior al for.", "Utiliza n if n >= 0 else 0 para cada n."], "El primer -2 se transforma en cero, no se descarta. Por eso la salida mantiene tres posiciones.");
lesson("comprension-dict", "Recibes una lista de palabras ASCII. Devuelve un diccionario palabra → longitud. Si una palabra se repite, aparece una sola clave. La lista vacía devuelve {}.", "Construir asociaciones mediante una comprensión de diccionario.", "{clave: valor for elemento in datos} crea un diccionario, no un conjunto. Una clave repetida reemplaza su valor anterior; aquí la longitud de la misma palabra siempre coincide.", "return {palabra: len(palabra) for palabra in data}", [[["sol","a","sol"],{sol:3,a:1}],[[],{}],[[""],{"":0}]], ["Cada palabra es la clave, no su posición.", "El valor se calcula con len.", "Escribe palabra: len(palabra) dentro de las llaves y añade el for."], "Dos apariciones de 'sol' no crean dos claves. Una palabra vacía es una clave válida con longitud cero.");
lesson("agrega", "Recibes una lista de enteros. Devuelve {total, minimo, maximo}. Para una lista vacía, total es 0 y los extremos son None (null en JSON). Conserva negativos y cero como datos válidos.", "Aplicar agregación con una política explícita para el vacío.", "sum([]) es 0. min y max de un iterable vacío fallan si no se proporciona default. min(valores, default=None) representa la ausencia de extremo sin inventar cero.", "return {'total': sum(data), 'minimo': min(data, default=None), 'maximo': max(data, default=None)}", [[[-4,-2],{total:-6,minimo:-4,maximo:-2}],[[],{total:0,minimo:null,maximo:null}],[[0],{total:0,minimo:0,maximo:0}]], ["Cero no sirve como máximo inicial para datos negativos.", "La ausencia de extremos se representa con None.", "Usa sum y min/max con default=None."], "En [-4, -2] el máximo es -2, no cero. El vacío no contiene extremos, aunque su suma sí tenga un valor neutro.");
lesson("clave-longitud", "Recibes una lista de palabras ASCII. Devuelve una lista nueva ordenada por longitud ascendente. Para longitudes iguales conserva el orden original. No modifiques la entrada.", "Pasar una función como clave de ordenación.", "sorted(palabras, key=len) pasa la función len sin llamarla: la ordenación la aplica a cada palabra. La ordenación es estable y mantiene el orden de elementos cuya clave coincide.", "return sorted(data, key=len)", [[["sol","a","luz"],["a","sol","luz"]],[[],[]],[["bb","aa","c"],["c","bb","aa"]]], ["No se pide ordenar alfabéticamente los empates.", "La clave es la longitud de cada palabra.", "Pasa key=len, no key=len(data)."], "'sol' y 'luz' miden tres y conservan su orden. sorted no necesita una lambda cuando la función len ya expresa el criterio.");
lesson("lambda-desempate", "Recibes palabras de letras a-z. Devuelve una lista nueva por longitud descendente y, en empate, orden alfabético ascendente. Conserva repeticiones y no cambies la entrada.", "Definir una clave compuesta con una función breve.", "lambda palabra: expresion equivale a una auxiliar que devuelve esa expresión. Las tuplas se comparan primero por su primer componente y después por el segundo. Usar -len pone las longitudes mayores delante sin invertir el alfabético.", "return sorted(data, key=lambda palabra: (-len(palabra), palabra))", [[["sol","a","luz"],["luz","sol","a"]],[[],[]],[["bb","aa","aa"],["aa","aa","bb"]]], ["Los criterios van en direcciones distintas.", "No uses reverse=True para ambos a la vez.", "La clave puede ser (-len(palabra), palabra)."], "Entre 'sol' y 'luz', ambas de tres letras, gana 'luz' por el criterio secundario. El signo negativo invierte solo el criterio numérico.");
lesson("formato-decimal", "Recibes {numero, decimales}: numero es finito entre -1000 y 1000; decimales es un entero de 0 a 4. Devuelve un texto con exactamente esa cantidad de decimales y punto como separador, siguiendo el formato nativo de Python.", "Formatear decimales sin confundir texto y valor numérico.", "f'{numero:.2f}' devuelve texto con dos decimales. Para una precisión variable, f'{numero:.{d}f}'. round solo devuelve un número y no garantiza ceros finales al convertirlo a texto. El formato usa el comportamiento de redondeo de float, no una regla financiera decimal.", "return f\"{data['numero']:.{data['decimales']}f}\"", [[{numero:3.5,decimales:2},"3.50"],[{numero:2.5,decimales:0},"2"],[{numero:0,decimales:3},"0.000"],[{numero:-1.25,decimales:1},"-1.2"]], ["La salida es texto y sus ceros importan.", "No basta con str(round(...)).", "Usa un f-string con .{decimales}f."], "Con 3.5 y dos decimales se devuelve '3.50'. El empate exacto 2.5 con precisión cero se representa como '2' por el redondeo al par.");
lesson("consulta-anidada", "Recibes {registro, alumno, curso}. registro asocia alumnos con diccionarios curso → nota, donde una nota es un entero de 0 a 100 o None. Devuelve la nota del curso, o None si falta alumno, curso o nota. Cero es una nota válida.", "Consultar dos niveles con respaldo sin perder el cero.", "registro.get(alumno, {}) devuelve un diccionario vacío si el alumno falta. Después .get(curso) obtiene la nota o None. No uses 'nota or None': cero también es falso pero debe conservarse.", "return data['registro'].get(data['alumno'], {}).get(data['curso'])", [[{registro:{ana:{mate:0}},alumno:"ana",curso:"mate"},0],[{registro:{},alumno:"ana",curso:"mate"},null],[{registro:{ana:{mate:null}},alumno:"ana",curso:"mate"},null],[{registro:{ana:{}},alumno:"ana",curso:"arte"},null]], ["Primero localiza el alumno, después el curso.", "El respaldo del alumno debe permitir consultar otra clave.", "Encadena get(alumno, {}) y get(curso)."], "Una nota 0 se entrega tal cual. La ausencia del alumno no provoca KeyError porque se continúa sobre un diccionario vacío.");

const copyAcademic = "registro = {}\nfor alumno, cursos in data['registro'].items():\n    registro[alumno] = dict(cursos)\n";
lesson("academia-inscribe", "Recibes {registro, alumno, curso}. Devuelve una copia del registro inscribiendo al alumno en ese curso con nota None si aún no está inscrito. Crea al alumno si falta. Si ya existe el curso, conserva su nota, incluso cero. No modifiques la entrada.", "Integrar creación de claves anidadas sin reemplazar datos previos.", "El modelo es alumno → curso → nota. Copia cada diccionario interior antes de modificarlo. setdefault conserva una clave existente; sirve tanto para el alumno como para el curso. Inscribir no equivale a calificar.", copyAcademic + "cursos = registro.setdefault(data['alumno'], {})\ncursos.setdefault(data['curso'], None)\nreturn registro", [[{registro:{},alumno:"ana",curso:"mate"},{ana:{mate:null}}],[{registro:{ana:{mate:0}},alumno:"ana",curso:"mate"},{ana:{mate:0}}],[{registro:{ana:{mate:8}},alumno:"ana",curso:"arte"},{ana:{mate:8,arte:null}}]], ["Un curso existente nunca debe perder su nota.", "Copia cada nivel y crea solamente las claves ausentes.", "Usa setdefault para el alumno y después para el curso."], "Inscribir de nuevo en mate no reinicia una nota cero. Los cursos nuevos se diferencian de los calificados mediante None.");
lesson("academia-califica", "Recibes {registro, alumno, curso, nota}, con nota entera. Devuelve una copia: cambia la nota solo si alumno y curso ya existen y 0 ≤ nota ≤ 100. En los demás casos conserva el registro sin cambios. No inscribas automáticamente ni modifiques la entrada.", "Validar una actualización de estado anidado antes de aplicarla.", "Inscripción y calificación tienen reglas distintas. Valida la existencia del curso y el rango antes de asignar. Una condición con and permite no consultar un alumno ausente; el cero pertenece al intervalo válido.", copyAcademic + "alumno, curso, nota = data['alumno'], data['curso'], data['nota']\nif alumno in registro and curso in registro[alumno] and 0 <= nota <= 100:\n    registro[alumno][curso] = nota\nreturn registro", [[{registro:{ana:{mate:null}},alumno:"ana",curso:"mate",nota:0},{ana:{mate:0}}],[{registro:{ana:{mate:8}},alumno:"ana",curso:"mate",nota:101},{ana:{mate:8}}],[{registro:{},alumno:"ana",curso:"mate",nota:50},{}],[{registro:{ana:{}},alumno:"ana",curso:"arte",nota:100},{ana:{}}],[{registro:{ana:{mate:8}},alumno:"ana",curso:"mate",nota:75},{ana:{mate:75}}],[{registro:{ana:{mate:8}},alumno:"ana",curso:"mate",nota:100},{ana:{mate:100}}],[{registro:{ana:{mate:8}},alumno:"ana",curso:"mate",nota:-1},{ana:{mate:8}}],[{registro:{ana:{mate:8,arte:6}},alumno:"ana",curso:"mate",nota:9},{ana:{mate:9,arte:6}}]], ["No crear cursos forma parte del contrato.", "Comprueba el rango con ambos extremos incluidos.", "Actualiza solo tras validar alumno, curso y 0 <= nota <= 100."], "Una nota inválida no borra la previa. Una calificación cero sí reemplaza None porque es un resultado válido, no ausencia. Las notas 75 y 100 reemplazan la anterior; -1 se rechaza y los otros cursos se conservan.");
lesson("academia-resume", "Recibes registro, un diccionario alumno → curso → nota entera de 0 a 100 o None. Devuelve {medias, clasificacion}: medias contiene cada alumno con su promedio de notas no None, o None si no tiene; clasificacion contiene solo alumnos con promedio, ordenados por media descendente y nombre a-z en empate. Los nombres son letras a-z.", "Integrar ausencia, agregación y desempates sobre registros académicos.", "Filtra None antes de calcular, no las notas falsas: cero participa. El promedio exige al menos una nota. Puedes usar el diccionario de medias como índice al ordenar los nombres y excluir primero las medias ausentes.", "medias = {}\nfor alumno, cursos in data.items():\n    notas = [n for n in cursos.values() if n is not None]\n    medias[alumno] = sum(notas) / len(notas) if notas else None\nclasificacion = [a for a in medias if medias[a] is not None]\nclasificacion = sorted(clasificacion, key=lambda a: (-medias[a], a))\nreturn {'medias': medias, 'clasificacion': clasificacion}", [[{ana:{mate:0,arte:100},bea:{mate:null}},{medias:{ana:50,bea:null},clasificacion:["ana"]}],[{},{medias:{},clasificacion:[]}],[{bea:{mate:80},ana:{arte:80},c:{mate:0}},{medias:{bea:80,ana:80,c:0},clasificacion:["ana","bea","c"]}],[{ana:{mate:80,arte:91},bea:{mate:85,leng:86},c:{mate:0}},{medias:{ana:85.5,bea:85.5,c:0},clasificacion:["ana","bea","c"]}],[{ana:{mate:1,arte:2},bea:{mate:null,arte:null}},{medias:{ana:1.5,bea:null},clasificacion:["ana"]}]], ["No confundas una nota cero con una nota pendiente.", "Calcula medias antes de ordenar sus nombres.", "Excluye None y usa la clave (-medias[alumno], alumno)."], "Ana con 0 y 100 tiene media 50; Bea sin notas no se clasifica. En un empate de medias se comparan los nombres, no el orden de llegada. Una media 85.5 no se trunca, y dos medias 85.5 se desempatan por nombre.");
lesson("iterador", "Recibes una lista de enteros. Crea un único iterador con iter(data). Devuelve [primera, resto]: primera contiene todos sus elementos al materializarlo por primera vez y resto lo que queda al materializarlo de nuevo. No crees un segundo iterador.", "Reconocer el agotamiento de un iterador.", "iter(lista) crea un recorrido consumible. list(iterador) lo consume hasta agotarlo. Una segunda materialización del mismo iterador no vuelve al comienzo; la lista original sí conserva sus elementos.", "recorrido = iter(data)\nprimera = list(recorrido)\nresto = list(recorrido)\nreturn [primera, resto]", [[[1,2],[[1,2],[]]],[[],[[],[]]],[[0],[[0],[]]]], ["La segunda lista usa el mismo objeto de recorrido.", "La primera materialización lo agota.", "Crea recorrido una sola vez y llama list(recorrido) dos veces."], "Después de producir 1 y 2, el iterador no tiene más elementos. No se vació data: se agotó ese recorrido.");
lesson("generador", "Recibes una lista de enteros. Devuelve la suma de sus cuadrados; para una lista vacía devuelve cero. Practica pasar un generador a sum en lugar de construir una lista intermedia.", "Consumir una expresión generadora mediante agregación.", "(n * n for n in valores) entrega cuadrados bajo demanda. sum consume esos valores sin necesitar la lista completa de cuadrados. Las pruebas comprueban el resultado, no el consumo de memoria de una implementación alternativa.", "return sum(n * n for n in data)", [[[-2,3],13],[[],0],[[0,1,1],2]], ["Los negativos también se elevan al cuadrado.", "sum acepta un iterable, no solo listas.", "Pasa n * n for n in data a sum."], "El total de [-2, 3] es 4 + 9 = 13. El generador entrega cada cuadrado una vez; el vacío conserva el neutro cero.");
lesson("map", "Recibes una lista de textos que representan enteros válidos entre -100 y 100. Devuelve esos enteros duplicados en el mismo orden. Practica map con una función auxiliar; las entradas no requieren recuperación de errores.", "Materializar una transformación mediante map.", "map(funcion, valores) aplica una función a cada elemento y devuelve un iterador. La función se pasa por nombre, sin paréntesis. list materializa los valores para devolver una salida JSON.", "def doble(texto):\n    return int(texto) * 2\nreturn list(map(doble, data))", [[["2","-1"],[4,-2]],[[],[]],[["0","3"],[0,6]]], ["Primero convierte cada texto, después multiplica.", "map recibe la función sin ejecutarla por adelantado.", "Devuelve list(map(doble, data))."], "La auxiliar recibe un texto cada vez. Multiplicar directamente el texto '2' produciría '22', no el número 4.");
lesson("filter", "Recibes una lista de registros {nombre, edad}, donde edad es un entero de 0 a 120. Devuelve los nombres de quienes tienen al menos 18 años, en orden original y sin quitar repeticiones. Practica filter y una auxiliar booleana.", "Separar un predicado de selección de la extracción de campos.", "filter(predicado, registros) conserva aquellos para los que el predicado devuelve verdadero. El registro no se transforma al filtrar; después puedes extraer su nombre con un recorrido o comprensión conocida.", "def mayor(persona):\n    return persona['edad'] >= 18\nreturn [p['nombre'] for p in filter(mayor, data)]", [[[{nombre:"ana",edad:18},{nombre:"bea",edad:17}],["ana"]],[[],[]],[[{nombre:"a",edad:30},{nombre:"a",edad:80}],["a","a"]]], ["Los 18 años están incluidos.", "El predicado selecciona registros, no nombres.", "Filtra con mayor y extrae nombre de cada registro aceptado."], "La condición determina la pertenencia, mientras que la comprensión final elige qué campo mostrar. Son tareas distintas.");

const copyContacts = "agenda = {}\nfor nombre, ficha in data['agenda'].items():\n    agenda[nombre] = dict(ficha)\n";
lesson("contactos-borra", "Recibes {agenda, nombre}, con el mismo modelo nombre normalizado → ficha {telefono, correo}. Devuelve una copia sin el contacto indicado, normalizando nombre con strip y lower. Si no existe, conserva todas las fichas. No modifiques la entrada ni borres otros contactos.", "Aplicar una política de identidad consistente al eliminar contactos.", "La misma normalización debe usarse al crear, editar y borrar. pop(nombre, None) permite eliminar sin fallar si la clave no existe. Esta operación no requiere buscar coincidencias parciales: se borra solo el nombre completo normalizado.", copyContacts + "nombre = data['nombre'].strip().lower()\nagenda.pop(nombre, None)\nreturn agenda", [[{agenda:{ana:{telefono:"1",correo:"a"},anabel:{telefono:"2",correo:"b"}},nombre:" ANA "},{anabel:{telefono:"2",correo:"b"}}],[{agenda:{},nombre:"ana"},{}],[{agenda:{ana:{telefono:"1",correo:"a"}},nombre:"bea"},{ana:{telefono:"1",correo:"a"}}]], ["Se elimina un nombre completo, no todos los que lo contienen.", "Normaliza antes de buscar la clave.", "Usa pop(nombre, None) en la copia de agenda."], "Borrar ANA normalizado elimina ana pero conserva anabel. Una clave ausente no modifica el estado.");
lesson("inventario-valora", "Recibes una lista de fichas {nombre, cantidad, precio_centimos}. Los nombres son únicos y de letras a-z; cantidad y precio_centimos son enteros de 0 a 10000. Devuelve {total_centimos, productos}: productos contiene {nombre, valor_centimos} por ficha, ordenados por valor descendente y nombre ascendente en empate. total_centimos suma sus valores. Sin productos devuelve total 0 y lista vacía. No cambies la entrada.", "Integrar cálculo monetario entero y reporte con desempates.", "El valor de una ficha es cantidad por precio en céntimos. Mantener enteros evita redondeo de dinero. Construye nuevas filas y ordénalas con una clave compuesta; sumar sus valores no requiere modificar el stock ni guardar archivos.", "productos = []\nfor ficha in data:\n    productos.append({'nombre': ficha['nombre'], 'valor_centimos': ficha['cantidad'] * ficha['precio_centimos']})\nproductos = sorted(productos, key=lambda p: (-p['valor_centimos'], p['nombre']))\nreturn {'total_centimos': sum(p['valor_centimos'] for p in productos), 'productos': productos}", [[[{nombre:"pan",cantidad:2,precio_centimos:125},{nombre:"agua",cantidad:1,precio_centimos:100}],{total_centimos:350,productos:[{nombre:"pan",valor_centimos:250},{nombre:"agua",valor_centimos:100}]}],[[],{total_centimos:0,productos:[]}],[[{nombre:"b",cantidad:0,precio_centimos:100},{nombre:"a",cantidad:2,precio_centimos:0}],{total_centimos:0,productos:[{nombre:"a",valor_centimos:0},{nombre:"b",valor_centimos:0}]}]], ["Multiplica por ficha antes de calcular el total.", "En empate, el nombre se ordena ascendente.", "Usa la clave (-valor_centimos, nombre) y suma los valores calculados."], "Dos unidades a 125 céntimos aportan 250 y el agua añade 100: total 350. El reporte no cambia las cantidades originales.");
lesson("contactos-crea", "Recibes {agenda, nombre, telefono, correo}. agenda usa nombres ya normalizados (strip y lower) como claves y fichas {telefono, correo}. Normaliza nombre: si queda vacío o ya existe, devuelve una copia sin cambios. En otro caso añade la ficha. No modifiques la entrada.", "Crear contactos con una política consistente de identidad.", "Normalizar antes de consultar evita tratar ' Ana ' y 'ana' como personas distintas. Copia las fichas para conservar el estado de entrada. Los teléfonos son texto: no pierdas ceros iniciales convirtiéndolos a números.", copyContacts + "nombre = data['nombre'].strip().lower()\nif nombre and nombre not in agenda:\n    agenda[nombre] = {'telefono': data['telefono'], 'correo': data['correo']}\nreturn agenda", [[{agenda:{},nombre:" ANA ",telefono:"012",correo:"a@b.es"},{ana:{telefono:"012",correo:"a@b.es"}}],[{agenda:{ana:{telefono:"1",correo:"x"}},nombre:"Ana",telefono:"2",correo:"y"},{ana:{telefono:"1",correo:"x"}}],[{agenda:{},nombre:" ",telefono:"1",correo:"x"},{}]], ["Normaliza antes de comprobar duplicados.", "Un nombre vacío tampoco se acepta.", "Añade la ficha solo si nombre es no vacío y no está en agenda."], "La variante de escritura ' ANA ' se guarda bajo ana. Repetir un contacto no reemplaza su teléfono: el estado devuelto permite observarlo.");
lesson("contactos-edita", "Recibes {agenda, nombre, cambios}. Normaliza nombre con strip y lower. Si existe, actualiza únicamente telefono y correo presentes en cambios con valor de texto; ignora otros campos y None. Permite texto vacío. Si falta el contacto, devuelve una copia sin cambios. No modifiques la entrada.", "Limitar una actualización a campos y tipos permitidos.", "Recorre cambios con items y comprueba el nombre del campo. isinstance(valor, str) distingue texto de None. No uses if valor: eliminaría el texto vacío que este contrato permite. Usa la misma normalización que al crear.", copyContacts + "nombre = data['nombre'].strip().lower()\nif nombre in agenda:\n    for campo, valor in data['cambios'].items():\n        if campo in ('telefono', 'correo') and isinstance(valor, str):\n            agenda[nombre][campo] = valor\nreturn agenda", [[{agenda:{ana:{telefono:"1",correo:"x"}},nombre:"  ANA  ",cambios:{telefono:"",otro:"no"}},{ana:{telefono:"",correo:"x"}}],[{agenda:{},nombre:"ana",cambios:{correo:"y"}},{}],[{agenda:{ana:{telefono:"1",correo:"x"}},nombre:"ana",cambios:{correo:null}},{ana:{telefono:"1",correo:"x"}}],[{agenda:{ana:{telefono:"1",correo:"x"}},nombre:"ana",cambios:{correo:"nuevo@x"}},{ana:{telefono:"1",correo:"nuevo@x"}}],[{agenda:{ana:{telefono:"1",correo:"x"}},nombre:"ana",cambios:{telefono:"2"}},{ana:{telefono:"2",correo:"x"}}],[{agenda:{ana:{telefono:"1",correo:"x"}},nombre:"ana",cambios:{telefono:"2",correo:"y"}},{ana:{telefono:"2",correo:"y"}}],[{agenda:{ana:{telefono:"1",correo:"x"}},nombre:"ana",cambios:{correo:5,telefono:null,nombre:"bea"}},{ana:{telefono:"1",correo:"x"}}]], ["Que un campo llegue en cambios no significa que esté permitido.", "Texto vacío es válido y None se ignora.", "Actualiza solo campos permitidos cuyo valor cumpla isinstance(valor, str)."], "Un teléfono vacío puede representar un borrado intencional. Un campo extraño o un valor no textual no debe introducir propiedades nuevas en el modelo. Correo y teléfono se actualizan por separado y juntos; la normalización con strip y lower encuentra a Ana.");
lesson("contactos-busca", "Recibes {agenda, filtros}, con fichas de telefono/correo y filtros de esos campos con valores de texto. Devuelve nombres ordenados a-z que cumplan todos los filtros: coincidencia parcial e insensible a mayúsculas. Un filtro de campo ausente rechaza la ficha. Sin filtros, devuelve todos. No cambies datos.", "Combinar criterios de búsqueda sin introducir sintaxis nueva.", "Una auxiliar puede comprobar una ficha y devolver False en la primera condición incumplida. El operador in sobre textos busca una parte. Normaliza solo para comparar, no para modificar los datos guardados. isinstance comprueba que el valor consultado sea texto.", "def cumple(ficha):\n    for campo, texto in data['filtros'].items():\n        if campo not in ficha or texto.lower() not in ficha[campo].lower():\n            return False\n    return True\nreturn sorted(nombre for nombre, ficha in data['agenda'].items() if cumple(ficha))", [[{agenda:{ana:{telefono:"123",correo:"A@EX.es"},bea:{telefono:"456",correo:"b@x.es"}},filtros:{correo:"ex",telefono:"2"}},["ana"]],[{agenda:{},filtros:{}},[]],[{agenda:{bea:{telefono:"1",correo:"b"},ana:{telefono:"2",correo:"a"}},filtros:{}},["ana","bea"]]], ["Todos los filtros deben cumplirse, no solo uno.", "Una primera diferencia permite rechazar esa ficha.", "Comprueba cada campo en una auxiliar y ordena los nombres aceptados."], "Exigir correo con 'ex' y teléfono con '2' selecciona solo ana. Con filtros vacíos ninguna condición rechaza las fichas.");
lesson("transforma-campo", "Recibes {registro, campo}. Los valores del registro son textos. Devuelve una copia donde, si campo existe, su texto esté sin espacios exteriores y en minúsculas. Conserva los otros campos y no modifiques el registro original.", "Aplicar una transformación puntual sobre una copia.", "dict(registro) basta aquí porque sus valores son textos inmutables, no contenedores. strip y lower producen textos nuevos. Comprueba que exista la clave antes de consultarla; no crees una clave ausente.", "copia = dict(data['registro'])\ncampo = data['campo']\nif campo in copia:\n    copia[campo] = copia[campo].strip().lower()\nreturn copia", [[{registro:{nombre:" ANA ",ciudad:"Quito"},campo:"nombre"},{nombre:"ana",ciudad:"Quito"}],[{registro:{},campo:"nombre"},{}],[{registro:{nombre:"A"},campo:"otro"},{nombre:"A"}]], ["La transformación se limita a una clave.", "No crees el campo si no existe.", "Copia el registro y aplica strip().lower() solo en campo."], "La ciudad conserva sus mayúsculas porque no tiene regla. La copia plana es suficiente con valores de texto; no sería universal para datos anidados.");
lesson("transforma-registros", "Recibes {registros, reglas}. Los registros contienen textos; reglas asocia campos con 'minusculas', 'trim' o 'numerico'. Devuelve copias con la regla de cada campo existente aplicada: lower, strip o conversión con int. Si int lanza ValueError, usa None para ese campo. Conserva campos sin regla, ignora reglas de campos ausentes y no modifiques originales. El texto numérico admite signo y espacios, no decimales.", "Integrar despacho por nombres y recuperación de errores por campo.", "JSON transporta nombres de operaciones, no funciones. Recorre cada registro y copia sus campos. La conversión int puede lanzar ValueError; captura ese error solo en la rama numérica, de modo que un campo inválido no interrumpa los demás registros.", "salida = []\nfor registro in data['registros']:\n    copia = dict(registro)\n    for campo, operacion in data['reglas'].items():\n        if campo not in copia:\n            continue\n        if operacion == 'minusculas':\n            copia[campo] = copia[campo].lower()\n        elif operacion == 'trim':\n            copia[campo] = copia[campo].strip()\n        elif operacion == 'numerico':\n            try:\n                copia[campo] = int(copia[campo])\n            except ValueError:\n                copia[campo] = None\n    salida.append(copia)\nreturn salida", [[{registros:[{nombre:"ANA",edad:" 18 "}],reglas:{nombre:"minusculas",edad:"numerico"}},[{nombre:"ana",edad:18}]],[{registros:[],reglas:{}},[]],[{registros:[{edad:"x",nombre:" A "},{edad:"0"}],reglas:{edad:"numerico",nombre:"trim",otro:"trim"}},[{edad:null,nombre:"A"},{edad:0}]]], ["Cada registro necesita su propia copia.", "Los nombres de las reglas deben coincidir con el contrato.", "Captura ValueError en numerico y continúa con los demás campos y registros."], "La edad inválida se convierte en None sin perder el nombre válido ni el registro siguiente. Cero convertido sigue siendo un entero válido.");
